draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw alpha dog
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  // Draw beta dog
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 50 * Math.sin(t), H/2, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 50 * Math.sin(t), H/2 + 15);
  ctx.lineTo(W/2 - 100 + 50 * Math.sin(t), H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 50 * Math.sin(t), H/2 + 25);
  ctx.lineTo(W/2 - 120 + 50 * Math.sin(t), H/2 + 35);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 50 * Math.sin(t), H/2 + 25);
  ctx.lineTo(W/2 - 80 + 50 * Math.sin(t), H/2 + 35);
  ctx.stroke();

  // Draw omega dog
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 30 * Math.cos(t), H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 30 * Math.cos(t), H/2 + 10);
  ctx.lineTo(W/2 + 100 + 30 * Math.cos(t), H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 30 * Math.cos(t), H/2 + 15);
  ctx.lineTo(W/2 + 90 + 30 * Math.cos(t), H/2 + 25);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 30 * Math.cos(t), H/2 + 15);
  ctx.lineTo(W/2 + 110 + 30 * Math.cos(t), H/2 + 25);
  ctx.stroke();

  ctx.restore();
}
